import sys
import math

class Scanner:
    def __init__(self, reader):
        self.reader = reader
        self.buffer = []

    def token(self, typ=str):
        while True:
            if self.buffer:
                return typ(self.buffer.pop())
            line = self.reader.readline()
            if not line:
                return None
            self.buffer = line.split()[::-1]

def factorize(n):
    ans = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            ans.append(d)
            n //= d
        d += 1
    if n > 1:
        ans.append(n)
    return ans

def solve():
    scan = Scanner(sys.stdin)
    n = scan.token(int)
    k = scan.token(int)

    factors = factorize(n)
    num_factors = len(factors)
    out = []

    if num_factors < k:
        print(-1)
        return

    for i in range(k - 1):
        out.append(str(factors[i]))

    last_factor = 1
    for i in range(k - 1, num_factors):
        last_factor *= factors[i]
    out.append(str(last_factor))

    print(" ".join(out))

if __name__ == "__main__":
    solve()

